String phrase(AppState state, String key) {
  final row = _rows[key];
  if (row == null || row.isEmpty) return key;
  final index = phraseCodes.indexOf(state.uiLanguage);
  if (index < 0 || index >= row.length) return row[0];
  return row[index];
}

